export function automateCopy(locale: WorkspaceLocale): AutomateRenderCopy {
  const base = COPY[locale];
  const state = (value: string) => value in EXECUTION_STATES[locale] ? EXECUTION_STATES[locale][value as keyof typeof EXECUTION_STATES[typeof locale]] : UNKNOWN[locale];
  const runStepMessage = (message: string) => {
    const simulatedNode = /^Simulated (trigger|action|condition|switch|loop|parallel|error|finally|approval|subflow|transform)$/.exec(message);
    if (!simulatedNode) return UNKNOWN_STEP_MESSAGE[locale];
    return base.simulated(NODE_TYPE_COPY[locale][simulatedNode[1] as AutomateNodeType]);
  };
  return {
    ...base,
    executionStatus: value => `${base.executionStatus('')}${state(value)}`,
    execution: value => `${base.execution('')}${state(value)}`,
    nodeType: type => NODE_TYPE_COPY[locale][type],
    validationCode: code => code.startsWith('preview-invalid:') ? VALIDATION_TEXT[locale].preview : VALIDATION_TEXT[locale][VALIDATION_GROUP[code as AutomateValidationCode] ?? 'graph'],
    accessibilityCode: code => ACCESSIBILITY_TEXT[locale][code as keyof typeof ACCESSIBILITY_TEXT[typeof locale]] ?? UNKNOWN[locale],
    runStepMessage,
  };
}
export function useAutomateCopy(): AutomateRenderCopy {
  const { locale } = useWorkspaceLocale();
  return automateCopy(locale);
}

export function automateNodeType(locale: WorkspaceLocale, type: string): string {
  return type in NODE_TYPE_COPY[locale] ? NODE_TYPE_COPY[locale][type as AutomateNodeType] : UNKNOWN[locale];
}
